{
  "title": "Rescue in the Ruined Crown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team studies a worn map at the edge of the ruined city.",
      "visual_description": "A windswept ridge overlooking a shattered skyline of broken spires; four figures crouch around an unrolled parchment held down by stones.",
      "characters": ["map_reader", "scout", "mage_helper", "sleepy_official"]
    },
    {
      "scene_number": 2,
      "caption": "The scout points out the distant castle gates.",
      "visual_description": "Foreground silhouette of the scout pointing; in the distance, enormous iron-banded gates loom under a bruised sky.",
      "characters": ["scout", "map_reader"]
    },
    {
      "scene_number": 3,
      "caption": "Frightened townspeople warn them away from the inner walls.",
      "visual_description": "A narrow lane of leaning houses; ragged townsfolk clutch bundles and gesture frantically at the heroes.",
      "characters": ["map_reader", "mage_helper", "frightened_townsfolk"]
    },
    {
      "scene_number": 4,
      "caption": "A cursed tower glows on the horizon, tempting them off course.",
      "visual_description": "A crooked tower wrapped in violet light pulses against the dusk; the team pauses at a crossroads of cracked flagstones.",
      "characters": ["map_reader", "scout", "mage_helper", "sleepy_official"]
    },
    {
      "scene_number": 5,
      "caption": "The map reader insists they stay on the rescue route.",
      "visual_description": "Close shot of the map reader tracing a charcoal line on parchment while the mage helper eyes the tower.",
      "characters": ["map_reader", "mage_helper"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol marches past the rubble.",
      "visual_description": "The team flattens behind a fallen statue as a column of helmeted guards clatters by with torches.",
      "characters": ["scout", "map_reader", "mage_helper", "sleepy_official", "armored_patrol"]
    },
    {
      "scene_number": 7,
      "caption": "Old royal banners flap above an abandoned courtyard.",
      "visual_description": "Tattered crimson banners hang from broken poles; the heroes cross a moonlit plaza strewn with shattered tiles.",
      "characters": ["scout", "map_reader", "sleepy_official"]
    },
    {
      "scene_number": 8,
      "caption": "A rumor of dragons rises with smoke from a far quarter.",
      "visual_description": "Distant rooftops trail thin smoke; a winged shape might or might not arc above the haze.",
      "characters": ["scout", "mage_helper"]
    },
    {
      "scene_number": 9,
      "caption": "The sleepy official almost wanders into a trap pit.",
      "visual_description": "A yawning official steps forward; the scout yanks him back by the collar as gravel skitters into a dark hole.",
      "characters": ["sleepy_official", "scout"]
    },
    {
      "scene_number": 10,
      "caption": "They reach a sealed magic door covered in runes.",
      "visual_description": "A tall stone door inscribed with glowing sigils; the mage helper raises both palms, light reflecting on the team's faces.",
      "characters": ["mage_helper", "map_reader", "scout", "sleepy_official"]
    },
    {
      "scene_number": 11,
      "caption": "The mage helper coaxes the runes open.",
      "visual_description": "Threads of pale blue light unravel from the door's surface and swirl around the mage's fingertips.",
      "characters": ["mage_helper"]
    },
    {
      "scene_number": 12,
      "caption": "Inside the keep, they find the captive in a barred cell.",
      "visual_description": "A low torchlit chamber with a heavy iron grate; a pale, weary prisoner reaches a hand through the bars.",
      "characters": ["map_reader", "scout", "captive"]
    },
    {
      "scene_number": 13,
      "caption": "The scout picks the lock as alarms begin to ring.",
      "visual_description": "Close on trembling hands and fine picks; in the background, a bell rope jerks and torchlight reddens the walls.",
      "characters": ["scout", "captive"]
    },
    {
      "scene_number": 14,
      "caption": "The armored patrol corners them in a collapsing hall.",
      "visual_description": "Dust rains from cracked vaults; armored figures advance with spears as the heroes back toward a broken archway.",
      "characters": ["armored_patrol", "scout", "map_reader", "mage_helper", "sleepy_official", "captive"]
    },
    {
      "scene_number": 15,
      "caption": "The mage helper drops a wall of shimmering light to buy time.",
      "visual_description": "A translucent curtain of gold sparks fills the corridor; silhouettes of guards press against it.",
      "characters": ["mage_helper", "armored_patrol"]
    },
    {
      "scene_number": 16,
      "caption": "They race through twisting alleys toward the river.",
      "visual_description": "Low-angle shot of running boots over wet cobbles; lanterns blur past leaning walls.",
      "characters": ["scout", "map_reader", "mage_helper", "sleepy_official", "captive"]
    },
    {
      "scene_number": 17,
      "caption": "The team crosses the long bridge above the dark river.",
      "visual_description": "A narrow stone bridge arcs over churning water; the heroes hurry across in single file as wind whips their cloaks.",
      "characters": ["scout", "map_reader", "mage_helper", "sleepy_official", "captive"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far bank, they look back at the burning city.",
      "visual_description": "Silhouettes on a grassy bluff watch distant flames flicker over broken towers; the captive leans gratefully on the map reader.",
      "characters": ["scout", "map_reader", "mage_helper", "sleepy_official", "captive"]
    }
  ]
}

